-- Execute no SQL Editor do Supabase. Use autenticação por e-mail/senha.
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',role text not null default 'field' check(role in ('admin','manager','supervisor','field')),created_at timestamptz not null default now());
create function public.create_profile() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''));return new;end$$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.create_profile();
create function public.my_role() returns text language sql stable security definer set search_path=public as $$select role from public.profiles where id=auth.uid()$$;
create function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select coalesce(public.my_role()='admin',false)$$;
alter table public.profiles enable row level security;
create policy "profiles read" on public.profiles for select to authenticated using(id=auth.uid() or public.my_role() in ('admin','manager','supervisor'));
create policy "profiles admin update" on public.profiles for update to authenticated using(public.is_admin()) with check(public.is_admin());
create table public.leads(id uuid primary key default gen_random_uuid(),name text not null,phone text,address text,sector text,provider text,monthly_price numeric(12,2),need text,status text default 'Novo',created_by uuid not null references public.profiles(id),created_at timestamptz default now());
create table public.activities(id uuid primary key default gen_random_uuid(),activity_type text not null,sector text,street text,started_at timestamptz,ended_at timestamptz,notes text,created_by uuid not null references public.profiles(id),created_at timestamptz default now());
create table public.leafleting(id uuid primary key default gen_random_uuid(),sector text,street text,activity_date date,flyers integer check(flyers>=0),properties integer check(properties>=0),status text default 'Pendente',notes text,created_by uuid not null references public.profiles(id),created_at timestamptz default now());
create table public.events(id uuid primary key default gen_random_uuid(),title text not null,event_type text,event_date date,sector text,status text default 'Planejada',cost numeric(12,2),notes text,created_by uuid not null references public.profiles(id),created_at timestamptz default now());
create table public.sales(id uuid primary key default gen_random_uuid(),lead_id uuid references public.leads(id),sale_type text not null,amount numeric(12,2) not null default 0,sale_date date,notes text,created_by uuid not null references public.profiles(id),created_at timestamptz default now());
do $$declare t text;begin foreach t in array array['leads','activities','leafleting','events','sales'] loop execute format('alter table public.%I enable row level security',t);execute format('create policy "read authorized" on public.%I for select to authenticated using(public.my_role() in (''admin'',''manager'',''supervisor'') or created_by=auth.uid())',t);execute format('create policy "insert own" on public.%I for insert to authenticated with check(created_by=auth.uid() and public.my_role() is not null)',t);execute format('create policy "update authorized" on public.%I for update to authenticated using(public.my_role() in (''admin'',''manager'',''supervisor'') or created_by=auth.uid()) with check(public.my_role() in (''admin'',''manager'',''supervisor'') or created_by=auth.uid())',t);end loop;end$$;
